from sqlalchemy import Boolean
from sqlalchemy import ForeignKey
import uuid

from sqlalchemy import Column, String, Numeric, DateTime, Integer, func
from sqlalchemy.dialects.postgresql import JSONB, UUID

from app.db.base import Base


class Sale(Base):
    __tablename__ = "sales"

    id = Column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
    company_id = Column(UUID(as_uuid=True), nullable=False)

    # Generated by the POS device before online or offline submission.
    # The unique index prevents a queued sale from being saved twice.
    client_sale_id = Column(
        UUID(as_uuid=True),
        nullable=True,
        unique=True,
        index=True,
    )

    # Original time recorded on the Android POS.
    client_created_at = Column(
        DateTime(timezone=True),
        nullable=True,
    )

    original_sale_id = Column(
        UUID(as_uuid=True),
        ForeignKey("sales.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )



    shop_id = Column(
        UUID(as_uuid=True),
        ForeignKey("shops.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )

    branch_id = Column(
        UUID(as_uuid=True),
        ForeignKey("branches.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )

    device_id = Column(
        UUID(as_uuid=True),
        ForeignKey("devices.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )


    employee_id = Column(
        UUID(as_uuid=True),
        ForeignKey("employees.id", ondelete="SET NULL"),
        nullable=True,
        index=True,
    )

    cashier_name = Column(
        String(160),
        nullable=True,
    )

    shop_name_snapshot = Column(
        String(160),
        nullable=True,
    )
    shop_address_snapshot = Column(
        JSONB,
        nullable=True,
    )
    branch_name_snapshot = Column(
        String(160),
        nullable=True,
    )
    pos_name_snapshot = Column(
        String(160),
        nullable=True,
    )
    pos_number_snapshot = Column(
        String(40),
        nullable=True,
    )
    receipt_footer_snapshot = Column(
        String,
        nullable=True,
    )

    receipt_number = Column(String(40), unique=True, nullable=False)

    subtotal_amount = Column(

        Numeric(12, 2),

        nullable=False,

        default=0,

    )

    tax_name = Column(String(40), nullable=True)

    tax_rate = Column(

        Numeric(7, 3),

        nullable=False,

        default=0,

    )

    tax_amount = Column(

        Numeric(12, 2),

        nullable=False,

        default=0,

    )

    tax_inclusive = Column(

        Boolean,

        nullable=False,

        default=False,

    )


    total_amount = Column(Numeric(12, 2), nullable=False, default=0)
    # Nullable by design: pre-Phase-2 and legacy-client rows do not contain
    # enough evidence to distinguish a discount from a price override.
    discount_amount = Column(Numeric(12, 2), nullable=True)
    amount_received = Column(Numeric(12, 2), nullable=False, default=0)
    change_due = Column(Numeric(12, 2), nullable=False, default=0)

    payment_method = Column(String(40), nullable=False, default="cash")
    status = Column(String(40), nullable=False, default="completed")
    refund_reason = Column(String(500), nullable=True)
    refund_method = Column(String(40), nullable=True)
    reprint_count = Column(Integer, nullable=False, default=0, server_default="0")
    last_reprinted_at = Column(DateTime(timezone=True), nullable=True)

    created_at = Column(
        DateTime(timezone=True),
        nullable=False,
        server_default=func.now(),
    )
